   585	/// e.g. you don't need to pay a conditional branching cost on every single
   586	/// action because the Zig compiler codegens separate code paths for every
   587	/// single action at comptime.
   588	pub fn Stream(comptime H: type) type {
   589	    return struct {
   590	        const Self = @This();
   591	
   592	        pub const Action = streampkg.Action;
   593	        pub const Handler = H;
   594	
   595	        const T = switch (@typeInfo(Handler)) {
   596	            .pointer => |p| p.child,
   597	            else => Handler,
   598	        };
   599	
   600	        handler: Handler,
   601	        parser: Parser,
   602	        utf8decoder: UTF8Decoder,
   603	        continuation: ?continuationpkg.Tracker,
   604	
   605	        pub const Options = struct {
   606	            /// The handler initial value, must be set.
   607	            handler: Handler,
   608	
   609	            /// Allocator to use. If this is not set then the stream
   610	            /// will be fully allocation free. There are some operations
   611	            /// that will be dropped in this case such as OSC 52 clipboard
   612	            /// ops.
   613	            allocator: ?Allocator = null,
   614	
   615	            /// Maximum size in bytes of the continuation suffix. If this is
   616	            /// null or zero then continuation tracking is disabled. This is
   617	            /// only applied when `allocator` is non-null; without an allocator
   618	            /// continuation tracking is disabled. Feeding this continuation
   619	            /// suffix into an equivalent stream at ground reconstructs the
   620	            /// unfinished state without repeating committed terminal effects.
   621	            /// Continuation tracking is only supported by TerminalStream.
   622	            continuation_max_bytes: ?usize = null,
   623	
   624	            /// The most bytes to keep from each OSC sequence whose number
   625	            /// the OSC parser does not implement. Zero, the default,
   626	            /// discards these sequences. Any other value sends them to the
   627	            /// handler as `osc_unknown` actions. See
   628	            /// `osc.Parser.unknown_max_bytes` for how the limit behaves.
   629	            ///
   630	            /// This only affects OSC. Other kinds of unknown sequences,
   631	            /// such as APC, are collected by the handler and have their own
   632	            /// limits there.
   633	            osc_unknown_max_bytes: usize = 0,
   634	        };
   635	
   636	        /// Initialize a stream. Without an allocator, operations that require
   637	        /// heap allocation are dropped.
   638	        ///
   639	        /// As a concrete example of something that requires heap allocation,
   640	        /// consider OSC 52 (clipboard operations) which can be arbitrarily
   641	        /// large.
   642	        ///
   643	        /// This takes ownership of the handler and will call deinit
   644	        /// when the stream is deinitialized.
   645	        pub fn init(options: Options) Self {
   646	            // Initialize the parser
   647	            var parser: Parser = .init();
   648	            if (options.allocator) |alloc| parser.osc_parser.alloc = alloc;
   649	            parser.osc_parser.unknown_max_bytes = options.osc_unknown_max_bytes;
   650	
   651	            // Initialize the continuation tracker if one is requested.
   652	            var tracker: ?continuationpkg.Tracker = null;
   653	            if (options.allocator) |alloc| {
   654	                if (options.continuation_max_bytes) |max_bytes| {
   655	                    if (max_bytes > 0) tracker = .init(alloc, max_bytes);
   656	                }
   657	            }
   658	
   659	            return .{
   660	                .handler = options.handler,
   661	                .parser = parser,
   662	                .utf8decoder = .{},
   663	                .continuation = tracker,
   664	            };
   665	        }

